input.command:
mkdir -p /tmp/rv && cd /tmp/rv && rm -rf proj && mkdir -p proj/.claude/scripts/lib proj/grimoires/loa && cp /workspace/pr/head/.claude/scripts/lib/dec-write-lib.sh proj/.claude/scripts/lib/ && cp /workspace/pr/head/.claude/scripts/validate-artifact.sh proj/.claude/scripts/ && cat > proj/.claude/scripts/compat-lib.sh <<'EOF'
sha256_portable(){ if [[ $# -gt 0 ]]; then sha256sum "$1"; else sha256sum; fi | cut -d' ' -f1; }
_date_to_epoch(){ date -u -d "$1" +%s; }
EOF
printf 'schema_version: 1\ndecisions: []\n' > proj/grimoires/loa/decisions.yaml; git -C proj init -q; sed -n 40,60p proj/.claude/scripts/validate-artifact.sh

cd /workspace/.eval/tmp/rv/h; awk --version 2>&1 | head -1; cat > /workspace/.eval/tmp/rv/s.md <<'EOF'
## 10. Open Questions

| Question | Owner | Due Date | Status | DEC |
|----------|-------|----------|--------|-----|
| Which DB? | me | 2026-11-01 | Unresolved | |
EOF
awk '
        function trim(s) { gsub(/^[[:space:]]+|[[:space:]]+$/, "", s); return s }
        /^## 10\. Open Questions/ { sec = 1; next }
        sec && /^## / { sec = 0 }
        !sec { next }
        /^\|/ {
            n = split($0, c, "|")
            if (!hdr) {
                hdr = 1
                for (i = 2; i < n; i++) { h = tolower(trim(c[i])); if (h == "status") st = i; if (h == "dec") dc = i }
                next
            }
            if ($0 ~ /^\|[-|: ]+\|?[[:space:]]*$/) next
            if (st && tolower(c[st]) ~ /resolved/) {
                cell = dc ? c[dc] : $0
                if (cell !~ /DEC-[0-9][0-9][0-9][0-9]/) printf "%d\n", NR
            }
        }
    ' /workspace/.eval/tmp/rv/s.md

